1	/**
2	 * Builds every internal href so route shapes live in one place. When the App
3	 * Router directory moves, this module changes and nothing else does — no
4	 * component or email template concatenates a path by hand.
5	 */
6	
7	function encodeSegment(segment: string): string {
8	  return encodeURIComponent(segment);
9	}
10	
11	function join(parts: readonly string[]): string {
12	  const cleaned = parts.filter((part) => part !== "" && part !== undefined);
13	  return `/${cleaned.join("/")}`;
14	}
15	
16	/** `/acme` or `/acme/issues/…` — the dashboard root for one organization. */
17	export function orgPath(orgSlug: string, ...segments: readonly string[]): string {
18	  return join([encodeSegment(orgSlug), ...segments.map(encodeSegment)]);
19	}
20	
21	export function projectPath(
22	  orgSlug: string,
23	  projectSlug: string,
24	  ...segments: readonly string[]
25	): string {
26	  return orgPath(orgSlug, "projects", projectSlug, ...segments);
27	}
28	
29	export function issuePath(
30	  orgSlug: string,
31	  projectSlug: string,
32	  issueNumber: number,
33	): string {
34	  return projectPath(orgSlug, projectSlug, "issues", String(issueNumber));
35	}
36	
37	export function settingsPath(orgSlug: string, section?: string): string {
38	  return section === undefined
39	    ? orgPath(orgSlug, "settings")
40	    : orgPath(orgSlug, "settings", section);
41	}
42	
43	/**
44	 * Appends query parameters, dropping `undefined` entries so callers can pass
45	 * an optional filter straight through. Existing parameters on `path` are kept.
46	 */
47	export function withSearchParams(
48	  path: string,
49	  params: Readonly<Record<string, string | number | undefined>>,
50	): string {
51	  const [base, existing = ""] = path.split("?", 2);
52	  const search = new URLSearchParams(existing);
53	
54	  for (const [key, value] of Object.entries(params)) {
55	    if (value === undefined) {
56	      search.delete(key);
57	      continue;
58	    }
59	    search.set(key, String(value));
60	  }
61	
62	  const query = search.toString();
63	  return query === "" ? (base ?? path) : `${base}?${query}`;
64	}
