    ...(author !== null ? { authorId: parseActorToken(author) } : {}),
    ...(labelIds.length > 0 ? { labelIds } : {}),
    ...(query !== null && query.length > 0 ? { query } : {}),
    ...(dueBefore !== null ? { dueBefore } : {}),
