/** Adds or removes one status without disturbing the other dimensions. */
export function toggleStatus(
  filter: IssueFilter,
  status: IssueStatus,
): IssueFilter {
  const current = filter.status ?? [];
  const next = current.includes(status)
    ? current.filter((value) => value !== status)
    : [...current, status];
  const { status: _dropped, ...rest } = filter;
  return next.length === 0 ? rest : { ...rest, status: next };
}

/** True when the filter's status is exactly this group's members — the "four
 *  clicks to get `open`" problem ADR 0009 calls out. */
function isStatusGroupActive(filter: IssueFilter, group: IssueStatusGroup): boolean {
  const current = filter.status ?? [];
  const members = expandStatusGroups([group]);
  return (
    current.length === members.length &&
    members.every((status) => current.includes(status))
  );
}

/** One click selects (or clears) every status in the group at once. */
export function toggleStatusGroup(
  filter: IssueFilter,
  group: IssueStatusGroup,
): IssueFilter {
  if (isStatusGroupActive(filter, group)) {
    const { status: _dropped, ...rest } = filter;
    return rest;
  }
  return { ...filter, status: [group] };
}

