cd "/private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/5b53de7c-008f-49c9-a7da-c6e5fdfd762f" && cat > tests/_tmp-sanity.test.ts << 'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);

import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import * as labelRepo from "@/server/repositories/label-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("sanity-adr9");
});

afterAll(() => {
  cleanup();
});

describe("ADR 0009 sanity", () => {
  it("assignee=null filters to unassigned only", async () => {
    const n1 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    await issueRepo.insertIssue(issueInput(tenant.org.id, tenant.project.id, { title: "Unassigned one", assigneeId: null }), tenant.userIds.owner, n1);
    const n2 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    await issueRepo.insertIssue(issueInput(tenant.org.id, tenant.project.id, { title: "Assigned one", assigneeId: tenant.userIds.member }), tenant.userIds.owner, n2);

    const page = await issueRepo.listIssues({ orgId: tenant.org.id, limit: 100, cursor: null, assigneeId: null });
    expect(page.items.every((i) => i.assigneeId === null)).toBe(true);
    expect(page.items.length).toBeGreaterThan(0);
  });

  it("status=open expands via the service/repo for a raw group literal", async () => {
    const page = await issueService.listIssues(tenant.actors.owner, {
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
      status: ["open"] as any,
    });
    expect(page.items.every((i) => i.status !== "done" && i.status !== "canceled")).toBe(true);
  });

  it("me resolves to the acting user for assigneeId", async () => {
    const page = await issueService.listIssues(tenant.actors.member, {
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
      assigneeId: "me" as any,
    });
    expect(page.items.every((i) => i.assigneeId === tenant.userIds.member)).toBe(true);
  });

  it("labels are all-of, not any-of", async () => {
    const labelA = await labelRepo.insertLabel({ orgId: tenant.org.id, name: "bug", color: "#ef4444", description: null });
    const labelB = await labelRepo.insertLabel({ orgId: tenant.org.id, name: "regression", color: "#111111", description: null });

    const nBoth = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const both = await issueRepo.insertIssue({ ...issueInput(tenant.org.id, tenant.project.id, { title: "Has both" }), labelIds: [labelA.id, labelB.id] }, tenant.userIds.owner, nBoth);

    const nOne = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    await issueRepo.insertIssue({ ...issueInput(tenant.org.id, tenant.project.id, { title: "Has one" }), labelIds: [labelA.id] }, tenant.userIds.owner, nOne);

    const page = await issueRepo.listIssues({ orgId: tenant.org.id, limit: 100, cursor: null, labelIds: [labelA.id, labelB.id] });
    expect(page.items.map((i) => i.id)).toEqual([both.id]);
  });

  it("due_before as a calendar date includes the whole day", async () => {
    const n = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const issue = await issueRepo.insertIssue({ ...issueInput(tenant.org.id, tenant.project.id, { title: "Due midday" }), dueAt: "2026-03-15T18:00:00.000Z" as any }, tenant.userIds.owner, n);

    const page = await issueRepo.listIssues({ orgId: tenant.org.id, limit: 100, cursor: null, dueBefore: "2026-03-15" as any });
    expect(page.items.map((i) => i.id)).toContain(issue.id);
  });

  it("archivedOnly lists archived issues and nothing else", async () => {
    const n = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const issue = await issueRepo.insertIssue(issueInput(tenant.org.id, tenant.project.id, { title: "To archive" }), tenant.userIds.owner, n);
    await issueRepo.archiveIssue(tenant.org.id, issue.id);

    const page = await issueRepo.listIssues({ orgId: tenant.org.id, limit: 100, cursor: null, archivedOnly: true } as any);
    expect(page.items.every((i) => i.archivedAt !== null)).toBe(true);
    expect(page.items.map((i) => i.id)).toContain(issue.id);
  });
});
EOF
